query BondPage($address: String!) {
  Bond(where: { id: { _eq: $address } }) { id account adapter policyHash phase raised released undrawn principalRecovery revenueCollected stakeRecovery pool totalSupply effectiveCap defaulted triggered createdAt }
  Issuer(where: { activeBond: { _eq: $address } }) { id issuer tier project projectApproved activeBond grossRevenue toInvestors payments firstRevenueAt asset volume }
}

query AccountEvidence($address: String!) {
  Issuer(where: { id: { _eq: $address } }) { id issuer tier project projectApproved activeBond grossRevenue toInvestors payments firstRevenueAt asset volume }
  DailyRevenue(where: { account: { _eq: $address } }, order_by: { day: asc }) { account day gross verified x402 }
  PayerTotal(where: { account: { _eq: $address } }, order_by: { amount: desc }) { account payer amount payments related reasons source }
}

query BondChecks($address: String!) {
  CovenantCheck(where: { bond: { _eq: $address } }, order_by: { observedAt: desc }, limit: 200) { bond result observedAt txHash }
}

